import openpyxl, os, sys, json
from openpyxl.utils import get_column_letter
input_path='/root/data/workbook.xlsx'
output_path='/root/output/result.xlsx'
orig=openpyxl.load_workbook(input_path, data_only=False)
wb=openpyxl.load_workbook(output_path, data_only=False)
ws=wb['Task']
errors=[]
print('Result exists:', os.path.exists(output_path), 'size:', os.path.getsize(output_path) if os.path.exists(output_path) else None)
print('Original sheets:', orig.sheetnames)
print('Result sheets:', wb.sheetnames)
if wb.sheetnames != orig.sheetnames:
    errors.append(f'Sheet names changed: {wb.sheetnames} vs {orig.sheetnames}')

def is_formula(v):
    return isinstance(v, str) and v.startswith('=')

# Validate formula regions.
lookup_ranges=[(12,17),(19,24),(26,31)]
for r1,r2 in lookup_ranges:
    for r in range(r1,r2+1):
        for c in range(8,13):
            v=ws.cell(r,c).value
            if not is_formula(v) or 'Data!' not in v or 'INDEX' not in v or 'MATCH' not in v:
                errors.append(f'Bad lookup formula {get_column_letter(c)}{r}: {v!r}')
            # Check relative/absolute pattern representative for each cell.
            col=get_column_letter(c)
            if f'$D{r}' not in v or f'{col}$10' not in v:
                errors.append(f'Bad lookup refs {col}{r}: {v!r}')

for r in range(35,41):
    off=r-35
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=({col}{12+off}-{col}{19+off})/{col}{26+off}*100'
        v=ws.cell(r,c).value
        if v != expected:
            errors.append(f'Bad gap formula {col}{r}: expected {expected}, got {v!r}')

summary_expected={42:'MIN',43:'MAX',44:'MEDIAN',45:'AVERAGE'}
for r,func in summary_expected.items():
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'={func}({col}35:{col}40)'
        if ws.cell(r,c).value != expected:
            errors.append(f'Bad summary {col}{r}: expected {expected}, got {ws.cell(r,c).value!r}')
for r,p in [(46,'0.25'),(47,'0.75')]:
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=PERCENTILE({col}35:{col}40,{p})'
        if ws.cell(r,c).value != expected:
            errors.append(f'Bad percentile {col}{r}: expected {expected}, got {ws.cell(r,c).value!r}')

for c in range(8,13):
    col=get_column_letter(c)
    expected=f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'
    v=ws.cell(50,c).value
    if v != expected or 'SUMPRODUCT' not in v:
        errors.append(f'Bad weighted formula {col}50: expected {expected}, got {v!r}')

# Verify only specified yellow/formula output cells changed (allow workbook metadata differences ignored). Compare Task cell values outside target regions and all Data cells.
targets=set()
for r1,r2 in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(r1,r2+1):
        for c in range(8,13):
            targets.add((r,c))
orig_ws=orig['Task']
for r in range(1, orig_ws.max_row+1):
    for c in range(1, orig_ws.max_column+1):
        if (r,c) not in targets and orig_ws.cell(r,c).value != ws.cell(r,c).value:
            errors.append(f'Unexpected Task change {get_column_letter(c)}{r}: {orig_ws.cell(r,c).value!r} -> {ws.cell(r,c).value!r}')
orig_data=orig['Data']; data=wb['Data']
for r in range(1, max(orig_data.max_row,data.max_row)+1):
    for c in range(1, max(orig_data.max_column,data.max_column)+1):
        if orig_data.cell(r,c).value != data.cell(r,c).value:
            errors.append(f'Unexpected Data change {get_column_letter(c)}{r}')

print('Validation sample formulas:')
for addr in ['H12','I12','L31','H35','I36','L40','H42','I43','J44','K45','L46','L47','H50','L50']:
    print(addr, ws[addr].value)

if errors:
    print('VALIDATION FAILED')
    for e in errors[:50]: print(e)
    print('error_count', len(errors))
    sys.exit(1)
print('VALIDATION PASSED')
